"""Settlement ward: cooperative, loaded chunks only, no terrain edits or forced chunks."""
import json

HORDE='sculk_zombie sculk_mite sculk_mite_aggressor sculk_spitter sculk_bee_infector sculk_bee_harvester sculk_hatcher sculk_vindicator sculk_spore_spewer sculk_ravager sculk_creeper sculk_phantom sculk_enderman sculk_witch sculk_vex sculk_guardian sculk_brood_hatcher sculk_brood_spitter sculk_brood_striker sculk_ghast sculk_leech sculk_stinger sculk_salmon sculk_squid sculk_pufferfish sculk_sheep'.split()

def generate_wards(DATA,F,fn,js,msg):
    def append(p,lines):
        path=F/(p+'.mcfunction');path.write_text(path.read_text(encoding='utf-8')+'\n'.join(lines)+'\n',encoding='utf-8')
    def say(s): return 'tellraw @s '+json.dumps({'text':s,'color':'aqua'},ensure_ascii=False)
    js(DATA/'ashes'/'tags'/'entity_types'/'horde.json',{'replace':False,'values':[{'id':'sculkhorde:'+n,'required':False} for n in HORDE]})
    js(DATA/'ashes'/'tags'/'entity_types'/'residents.json',{'replace':False,'values':['minecraft:villager',{'id':'minecolonies:citizen','required':False}]})
    js(DATA/'ashes'/'advancements'/'ward'/'registered.json',{'criteria':{'registered':{'trigger':'minecraft:impossible'}}})
    append('load',['scoreboard objectives add ashes_ward trigger','scoreboard objectives add award_have dummy','scoreboard objectives add award_cd dummy','scoreboard objectives add award_count dummy'])
    append('player',['scoreboard players enable @s ashes_ward','execute if score @s ashes_ward matches 1 run function ashes:ward/request','execute if score @s ashes_ward matches 2 run function ashes:ward/status','scoreboard players set @s ashes_ward 0'])
    append('second',['execute in minecraft:overworld as @e[type=minecraft:marker,tag=ashes_ward] at @s run function ashes:ward/tick'])
    append('skills/menu',['tellraw @s '+json.dumps([{'text':'[Активировать обелиск]','color':'aqua','clickEvent':{'action':'run_command','value':'/trigger ashes_ward set 1'}},{'text':'  '},{'text':'[Проверить рубеж]','color':'green','clickEvent':{'action':'run_command','value':'/trigger ashes_ward set 2'}}],ensure_ascii=False)])
    fn('ward/request',['execute unless dimension minecraft:overworld run '+say('Обелиски работают только в обычном мире.'),'execute if dimension minecraft:overworld unless block ~ ~-1 ~ minecraft:lodestone run '+say('Встань на магнетит. Нужен один оберег рубежа.'),'execute if dimension minecraft:overworld if block ~ ~-1 ~ minecraft:lodestone align xyz positioned ~0.5 ~-1 ~0.5 run function ashes:ward/validate'])
    fn('ward/validate',['execute store result score @s award_have run clear @s kubejs:ward_charm 0','execute store result score @s award_count if entity @e[type=minecraft:marker,tag=ashes_ward]','execute if entity @e[type=minecraft:marker,tag=ashes_ward,distance=..32] run '+say('В пределах 32 блоков уже есть рубеж.'),'execute if score @s award_have matches 0 run '+say('Изготовь оберег рубежа.'),'execute if score @s award_count matches 64.. run '+say('Достигнут предел 64 загруженных обелисков.'),'execute unless entity @e[type=minecraft:marker,tag=ashes_ward,distance=..32] if score @s award_have matches 1.. if score @s award_count matches ..63 run function ashes:ward/install'])
    fn('ward/install',['summon minecraft:marker ~ ~ ~ {Tags:["ashes_ward"]}','clear @s kubejs:ward_charm 1','advancement grant @s only ashes:ward/registered','particle minecraft:happy_villager ~ ~1 ~ 0.7 0.8 0.7 0.1 40 normal @a[distance=..24]','playsound minecraft:block.beacon.activate player @a[distance=..24] ~ ~ ~ 0.8 1',say('Рубеж активен. Радиус поддержки 24 блока. Для земли возведи штатный защитный контур.')])
    fn('ward/status',['execute if entity @e[type=minecraft:marker,tag=ashes_ward,distance=..24] run '+say('Ты внутри радиуса поддержки обелиска.'),'execute unless entity @e[type=minecraft:marker,tag=ashes_ward,distance=..24] run '+say('Поблизости нет активного обелиска.')])
    fn('ward/tick',['execute unless block ~ ~ ~ minecraft:lodestone run kill @s','execute if block ~ ~ ~ minecraft:lodestone run function ashes:ward/active'])
    fn('ward/active',['scoreboard players add @s award_cd 0','execute if score @s award_cd matches 1.. run scoreboard players remove @s award_cd 1','execute if entity @a[distance=..48] if entity @e[type=#ashes:horde,distance=..32] run function ashes:ward/defend'])
    fn('ward/defend',['effect give @a[distance=..24] minecraft:resistance 3 0 true','effect give @e[type=#ashes:residents,distance=..24] minecraft:resistance 3 0 true','effect give @e[type=#ashes:horde,distance=..24] minecraft:weakness 3 0 true','effect give @e[type=#ashes:horde,distance=..24] minecraft:slowness 3 0 true','execute if score @s award_cd matches 0 run function ashes:ward/alert'])
    fn('ward/alert',['scoreboard players set @s award_cd 30','title @a[distance=..48] actionbar {"text":"⚠ Скверна приближается к рубежу!","color":"red"}','playsound minecraft:block.bell.use player @a[distance=..48] ~ ~ ~ 1 0.7','particle minecraft:soul_fire_flame ~ ~1 ~ 0.6 0.8 0.6 0.04 25 normal @a[distance=..48]'])
